     });
 
     const res = await fetch(`${baseURL}/encontros/enc_5e6f7a8b/codigo`);
 
     assert.equal(res.status, 401);
     const body = await res.json();
     assert.equal(body.erro, 'USUARIO_DESCONHECIDO');
   } finally {
