         id TEXT PRIMARY KEY,
         atividadeId TEXT,
         participanteId TEXT,
         status TEXT
       )`);
 
       db.run(`CREATE TABLE IF NOT EXISTS presencas (
         id TEXT PRIMARY KEY,
         encontroId TEXT,
         participanteId TEXT,
